<template><div><div class="page-head"><div><h1>Inventory</h1><p class="muted">Stock levels and adjustments.</p></div></div><div class="metrics"><div v-for="m in metrics" :key="m.label" class="metric card"><span>{{m.label}}</span><b>{{m.value}}</b></div></div><section class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>SKU</th><th>Product</th><th>Category</th><th>Stock</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td>{{p.sku}}</td><td><b>{{p.name}}</b></td><td>{{p.category}}</td><td><b>{{p.stock}}</b></td><td><span :class="['badge',p.stock===0?'red':p.stock<5?'yellow':'green']">{{p.stock===0?'Out of stock':p.stock<5?'Low stock':'Healthy'}}</span></td><td><button class="btn secondary small" @click="selected=p">Adjust</button></td></tr></tbody></table></div></section><div v-if="selected" class="overlay" @click.self="selected=null"><div class="modal card"><div class="page-head"><h3>Adjust stock</h3><button @click="selected=null">×</button></div><p class="muted">{{selected.name}} · {{selected.sku}}</p><label>Quantity<input v-model.number="quantity" type="number" class="input"/></label><label>Reason<select class="select"><option>Restock</option><option>Correction</option><option>Damaged</option></select></label><button class="btn" @click="adjust">Confirm adjustment</button></div></div></div></template>
<script setup lang="ts">import {ref} from 'vue';import {products} from '../services/mock';const metrics=[{label:'Total units',value:'1,842'},{label:'Low stock',value:'12'},{label:'Out of stock',value:'4'}];const selected=ref<any>(null),quantity=ref(1);function adjust(){if(selected.value){selected.value.stock=Math.max(0,selected.value.stock+quantity.value)}selected.value=null}</script>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:16px}.metric{padding:18px;display:grid;gap:8px}.metric span{color:#777}.metric b{font-size:25px}.table-card{padding:0}.small{padding:7px 10px;font-size:11px}.overlay{position:fixed;inset:0;background:#0008;display:grid;place-items:center;z-index:50;padding:20px}.modal{width:min(100%,460px);padding:22px;display:grid;gap:14px}.modal .page-head{margin:0}.modal .page-head h3{margin:0}.modal label{display:grid;gap:7px;font-weight:600;font-size:12px}@media(max-width:600px){.metrics{grid-template-columns:1fr}.table{min-width:700px}}
</style>
